// /etc/polkit-1/rules.d/49-atoll-pool.rules: Atoll's polkit rule for the pool home-media, which atoll polkit-rule prints
// (deploy/README.md). polkitd reads it before 50-atoll.rules, the .deb's, which lets the account atoll start any mount
// unit: with it, atoll may start the mount units of the pool's disks below, as the remount after a USB reset does, and
// the start of any other mount unit is refused. Print it again after atoll disk add, remove, replace or fail: a disk
// whose unit is not below, the daemon mounts itself, not through systemd.
polkit.addRule(function (action, subject) {
	var units = [
		"mnt-disk1.mount", // t1
		"srv-dev\\x2ddisk\\x2dby\\x2duuid\\x2d1234\\x2dABCD.mount", // t2
		"mnt-Vid\\xc3\\xa9os.mount", // u1
		"mnt-My\\x20Disk.mount" // t4
	];
	// Left out: t3 (failed).
	if (action.id !== "org.freedesktop.systemd1.manage-units" || subject.user !== "atoll" ||
		action.lookup("verb") !== "start") {
		return polkit.Result.NOT_HANDLED;
	}
	var unit = action.lookup("unit") || "";
	if (units.indexOf(unit) >= 0) {
		return polkit.Result.YES;
	}
	if (/\.mount$/.test(unit)) {
		return polkit.Result.NO;
	}
	return polkit.Result.NOT_HANDLED;
});
